function list(){const query=$('search').value.toLowerCase();$('list').replaceChildren();const unique=places.filter((a,i)=>places.findIndex(b=>b.name===a.name)===i).filter(a=>category==='all'||(category==='city'?a.kind==='City'||a.kind==='Lost settlement':a.kind==='Region')).filter(a=>a.name.toLowerCase().includes(query));for(const a of unique){const row=document.createElement('div');row.className='location';const link=document.createElement('a');link.href=wiki(a.name);link.target='_blank';link.rel='noopener';link.append(document.createTextNode(a.name+' ↗'));const small=document.createElement('small');small.textContent=a.kind;link.append(small);const btn=document.createElement('button');btn.textContent='⌖';btn.title='Focus '+a.name;btn.setAttribute('aria-label','Focus '+a.name);btn.onclick=()=>focusPlace(a);row.append(link,btn);$('list').append(row)}if(!unique.length)$('list').textContent='No matching places.'}
